const FA_SORT=[['ovr','綜合能力高→低'],['salary','年薪低→高'],['age','年齡小→大']];
function faPosGroup(r,p){if(r.pitcher)return (p?.role==='SP'||p?.role==='TWP')?'SP':'RP';const x=r.position;return x==='C'?'C':['1B','2B','3B','SS','IF'].includes(x)?'IF':['LF','CF','RF','OF'].includes(x)?'OF':x==='DH'?'DH':'IF';}
function faAgeOk(a){if(faAge==='all'||a==null)return faAge==='all';return faAge==='u25'?a<=25:faAge==='26-30'?a>=26&&a<=30:faAge==='31-34'?a>=31&&a<=34:a>=35;}
const rankMemo=new WeakMap();
function leagueRankText(p){let m=rankMemo.get(data);if(!m){m={};const sorted=k=>data.players.filter(q=>k==='P'?hasPitch(q)&&!hasBat(q):hasBat(q)).sort((a,b)=>ovr(b)-ovr(a)).map(q=>q.id);m.P=sorted('P');m.B=sorted('B');rankMemo.set(data,m);}const k=hasPitch(p)&&!hasBat(p)?'P':'B',i=m[k].indexOf(p.id);return i<0?'':`${LEAGUE_SHORT[state.league]||''}${k==='P'?'投手':'打者'}第 ${i+1}`;}
const isKnownSafe=p=>!world||isKnown(world,p,state.league);
